[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>ClipCast — One video is worth a thousand words</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Plus+Jakarta+Sans:wght@500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --primary: #7C3AED;
      --primary-dark: #6D28D9;
      --primary-light: #A78BFA;
      --accent: #FF613D;
      --accent-dark: #E5532D;
      --text: #292A2E;
      --text-secondary: #6B7280;
      --bg: #FFFFFF;
      --bg-secondary: #F9FAFB;
      --bg-tertiary: #F3F4F6;
      --border: #E5E7EB;
      --white: #FFFFFF;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);
      --radius: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --container: 1200px;
      --nav-height: 72px;
    }
    html { scroll-behavior: smooth; }
    body { font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif; color: var(--text); background: var(--bg); line-height: 1.6; -webkit-font-smoothing: antialiased; }
    h1, h2, h3, h4, h5, h6 { font-family: 'Plus Jakarta Sans', sans-serif; font-weight: 700; line-height: 1.2; }
    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }
    .container { max-width: var(--container); margin: 0 auto; padding: 0 24px; }
    .btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 12px 24px; border-radius: var(--radius); font-weight: 600; font-size: 15px; cursor: pointer; transition: all 0.2s ease; border: none; white-space: nowrap; }
    .btn-primary { background: var(--primary); color: var(--white); }
    .btn-primary:hover { background: var(--primary-dark); transform: translateY(-1px); box-shadow: var(--shadow-lg); }
    .btn-secondary { background: var(--white); color: var(--text); border: 1px solid var(--border); }
    .btn-secondary:hover { background: var(--bg-secondary); }
    .btn-accent { background: var(--accent); color: var(--white); }
    .btn-accent:hover { background: var(--accent-dark); transform: translateY(-1px); box-shadow: var(--shadow-lg); }
    .btn-lg { padding: 16px 32px; font-size: 16px; }
    .text-gradient { background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }

    /* Navigation */
    .nav { position: fixed; top: 0; left: 0; right: 0; height: var(--nav-height); background: rgba(255,255,255,0.95); backdrop-filter: blur(10px); border-bottom: 1px solid var(--border); z-index: 1000; }
    .nav-inner { max-width: var(--container); margin: 0 auto; padding: 0 24px; height: 100%; display: flex; align-items: center; justify-content: space-between; }
    .nav-logo { font-family: 'Plus Jakarta Sans', sans-serif; font-weight: 800; font-size: 22px; color: var(--primary); display: flex; align-items: center; gap: 8px; }
    .nav-logo svg { width: 32px; height: 32px; }
    .nav-links { display: flex; align-items: center; gap: 32px; }
    .nav-link { font-weight: 500; font-size: 15px; color: var(--text-secondary); transition: color 0.2s; }
    .nav-link:hover { color: var(--primary); }
    .nav-cta { display: flex; align-items: center; gap: 12px; }
    .nav-actions { display: flex; align-items: center; gap: 8px; }

    /* Hero Section */
    .hero { padding: calc(var(--nav-height) + 80px) 0 80px; background: linear-gradient(180deg, #F5F3FF 0%, var(--bg) 100%); }
    .hero-inner { max-width: var(--container); margin: 0 auto; padding: 0 24px; display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
    .hero-badge { display: inline-flex; align-items: center; gap: 8px; padding: 6px 14px; background: rgba(124, 58, 237, 0.1); border-radius: 100px; font-size: 13px; font-weight: 600; color: var(--primary); margin-bottom: 24px; }
    .hero-badge span { background: var(--primary); color: white; padding: 2px 8px; border-radius: 100px; font-size: 11px; }
    .hero h1 { font-size: 56px; font-weight: 800; line-height: 1.1; margin-bottom: 24px; letter-spacing: -0.02em; }
    .hero-subtitle { font-size: 20px; color: var(--text-secondary); margin-bottom: 32px; line-height: 1.6; }
    .hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }
    .hero-visual { position: relative; }
    .hero-card { background: var(--white); border-radius: var(--radius-xl); box-shadow: var(--shadow-xl); padding: 32px; position: relative; overflow: hidden; }
    .hero-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 4px; background: linear-gradient(90deg, var(--primary), var(--accent)); }
    .hero-video-placeholder { background: linear-gradient(135deg, #E9D5FF 0%, #C4B5FD 100%); border-radius: var(--radius-lg); aspect-ratio: 16/9; display: flex; align-items: center; justify-content: center; margin-bottom: 24px; }
    .hero-video-placeholder svg { width: 64px; height: 64px; color: var(--primary); }
    .hero-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
    .hero-stat { text-align: center; padding: 16px; background: var(--bg-secondary); border-radius: var(--radius); }
    .hero-stat-value { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 24px; font-weight: 700; color: var(--primary); }
    .hero-stat-label { font-size: 13px; color: var(--text-secondary); }

    /* Logo Bar */
    .logo-bar { padding: 48px 0; background: var(--bg-secondary); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
    .logo-bar p { text-align: center; font-size: 14px; color: var(--text-secondary); margin-bottom: 24px; text-transform: uppercase; letter-spacing: 1px; font-weight: 500; }
    .logo-bar-logos { display: flex; align-items: center; justify-content: center; gap: 48px; flex-wrap: wrap; opacity: 0.6; }
    .logo-bar-logos span { font-family: 'Plus Jakarta Sans', sans-serif; font-weight: 700; font-size: 20px; color: var(--text); }

    /* Feature Highlight - AI Bug Reports */
    .feature-highlight { padding: 80px 0; }
    .feature-highlight-inner { max-width: var(--container); margin: 0 auto; padding: 0 24px; display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
    .feature-highlight.reverse { direction: rtl; }
    .feature-highlight.reverse > * { direction: ltr; }
    .feature-label { display: inline-flex; align-items: center; gap: 8px; padding: 6px 14px; background: rgba(255, 97, 61, 0.1); border-radius: 100px; font-size: 13px; font-weight: 600; color: var(--accent); margin-bottom: 16px; width: fit-content; }
    .feature-label span { background: var(--accent); color: white; padding: 2px 8px; border-radius: 100px; font-size: 11px; }
    .feature-highlight h2 { font-size: 40px; margin-bottom: 16px; letter-spacing: -0.02em; }
    .feature-highlight p { font-size: 17px; color: var(--text-secondary); margin-bottom: 24px; line-height: 1.7; }
    .feature-highlight-visual { background: linear-gradient(135deg, #FEF3C7 0%, #FDE68A 100%); border-radius: var(--radius-xl); padding: 32px; position: relative; overflow: hidden; }
    .feature-card { background: var(--white); border-radius: var(--radius-lg); padding: 24px; box-shadow: var(--shadow-lg); }
    .feature-card-header { display: flex; align-items: center; gap: 12px; margin-bottom: 16px; }
    .feature-card-icon { width: 40px; height: 40px; background: var(--primary); border-radius: var(--radius); display: flex; align-items: center; justify-content: center; color: white; }
    .feature-card-title { font-weight: 600; font-size: 15px; }
    .feature-card-body { font-size: 14px; color: var(--text-secondary); line-height: 1.6; }
    .bug-report-tag { display: inline-flex; align-items: center; gap: 6px; padding: 4px 12px; background: #DBEAFE; color: #1E40AF; border-radius: 100px; font-size: 12px; font-weight: 500; margin-top: 12px; }

    /* Screen Recorder */
    .screen-recorder { padding: 80px 0; background: var(--bg-secondary); }
    .section-header { text-align: center; max-width: 640px; margin: 0 auto 48px; }
    .section-header h2 { font-size: 40px; margin-bottom: 16px; letter-spacing: -0.02em; }
    .section-header p { font-size: 18px; color: var(--text-secondary); }
    .recorder-features { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 48px; }
    .recorder-feature { background: var(--white); border-radius: var(--radius-lg); padding: 32px; box-shadow: var(--shadow-sm); border: 1px solid var(--border); transition: all 0.2s; }
    .recorder-feature:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
    .recorder-feature-icon { width: 48px; height: 48px; background: linear-gradient(135deg, var(--primary-light), var(--primary)); border-radius: var(--radius); display: flex; align-items: center; justify-content: center; color: white; margin-bottom: 16px; }
    .recorder-feature h3 { font-size: 18px; margin-bottom: 8px; }
    .recorder-feature p { font-size: 14px; color: var(--text-secondary); line-height: 1.6; }

    /* Video Editor */
    .video-editor { padding: 80px 0; }
    .video-editor-inner { max-width: var(--container); margin: 0 auto; padding: 0 24px; }
    .editor-features { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; margin-top: 48px; }
    .editor-feature { padding: 32px; background: var(--bg-secondary); border-radius: var(--radius-lg); border: 1px solid var(--border); }
    .editor-feature-icon { width: 48px; height: 48px; background: var(--primary); border-radius: var(--radius); display: flex; align-items: center; justify-content: center; color: white; margin-bottom: 20px; }
    .editor-feature h3 { font-size: 18px; margin-bottom: 12px; font-weight: 700; }
    .editor-feature p { font-size: 15px; color: var(--text-secondary); line-height: 1.7; }

    /* Integrations */
    .integrations { padding: 80px 0; background: linear-gradient(180deg, var(--bg) 0%, #F5F3FF 100%); }
    .integration-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px; margin-top: 48px; }
    .integration-item { background: var(--white); border-radius: var(--radius); padding: 24px; display: flex; align-items: center; justify-content: center; border: 1px solid var(--border); transition: all 0.2s; cursor: pointer; }
    .integration-item:hover { border-color: var(--primary); box-shadow: var(--shadow); transform: translateY(-2px); }
    .integration-item span { font-weight: 600; font-size: 14px; color: var(--text); }

    /* Engagement */
    .engagement { padding: 80px 0; background: var(--bg-secondary); }
    .engagement-cards { display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px; margin-top: 48px; }
    .engagement-card { background: var(--white); border-radius: var(--radius-xl); padding: 40px; box-shadow: var(--shadow-sm); border: 1px solid var(--border); }
    .engagement-card h3 { font-size: 24px; margin-bottom: 16px; }
    .engagement-card p { font-size: 16px; color: var(--text-secondary); line-height: 1.7; margin-bottom: 24px; }
    .engagement-list { list-style: none; }
    .engagement-list li { display: flex; align-items: flex-start; gap: 12px; margin-bottom: 12px; font-size: 15px; color: var(--text-secondary); }
    .engagement-list li svg { width: 20px; height: 20px; color: var(--primary); flex-shrink: 0; margin-top: 2px; }

    /* Security */
    .security { padding: 80px 0; }
    .security-inner { max-width: var(--container); margin: 0 auto; padding: 0 24px; display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
    .security h2 { font-size: 40px; margin-bottom: 16px; letter-spacing: -0.02em; }
    .security p { font-size: 17px; color: var(--text-secondary); margin-bottom: 32px; line-height: 1.7; }
    .security-features { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
    .security-feature { display: flex; align-items: center; gap: 12px; padding: 16px; background: var(--bg-secondary); border-radius: var(--radius); }
    .security-feature svg { width: 24px; height: 24px; color: var(--primary); }
    .security-feature span { font-weight: 500; font-size: 14px; }
    .security-visual { background: linear-gradient(135deg, #ECFDF5 0%, #D1FAE5 100%); border-radius: var(--radius-xl); padding: 48px; display: flex; align-items: center; justify-content: center; }
    .security-badge { background: var(--white); border-radius: var(--radius-lg); padding: 32px; box-shadow: var(--shadow-lg); text-align: center; }
    .security-badge-icon { width: 64px; height: 64px; background: #10B981; border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 16px; }
    .security-badge-icon svg { width: 32px; height: 32px; color: white; }
    .security-badge h4 { font-size: 18px; margin-bottom: 8px; }
    .security-badge p { font-size: 14px; color: var(--text-secondary); }

    /* Use Cases */
    .use-cases { padding: 80px 0; background: var(--bg-secondary); }
    .use-case-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 48px; }
    .use-case-card { background: var(--white); border-radius: var(--radius-lg); padding: 32px; text-align: center; border: 1px solid var(--border); transition: all 0.2s; cursor: pointer; }
    .use-case-card:hover { border-color: var(--primary); box-shadow: var(--shadow-lg); transform: translateY(-4px); }
    .use-case-icon { width: 56px; height: 56px; background: linear-gradient(135deg, var(--primary-light), var(--primary)); border-radius: var(--radius); display: flex; align-items: center; justify-content: center; margin: 0 auto 20px; color: white; }
    .use-case-card h3 { font-size: 18px; margin-bottom: 8px; }
    .use-case-card p { font-size: 14px; color: var(--text-secondary); line-height: 1.6; }

    /* Features Grid */
    .features-grid-section { padding: 80px 0; }
    .features-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 48px; }
    .feature-grid-item { background: var(--bg-secondary); border-radius: var(--radius-lg); padding: 28px; border: 1px solid var(--border); transition: all 0.2s; }
    .feature-grid-item:hover { border-color: var(--primary); background: var(--white); }
    .feature-grid-item h4 { font-size: 16px; margin-bottom: 8px; display: flex; align-items: center; gap: 10px; }
    .feature-grid-item h4 svg { width: 20px; height: 20px; color: var(--primary); }
    .feature-grid-item p { font-size: 14px; color: var(--text-secondary); line-height: 1.6; }

    /* Blog */
    .blog { padding: 80px 0; background: var(--bg-secondary); }
    .blog-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px; margin-top: 48px; }
    .blog-card { background: var(--white); border-radius: var(--radius-lg); overflow: hidden; border: 1px solid var(--border); transition: all 0.2s; }
    .blog-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
    .blog-card-image { height: 180px; background: linear-gradient(135deg, #E9D5FF 0%, #C4B5FD 100%); display: flex; align-items: center; justify-content: center; }
    .blog-card-image svg { width: 48px; height: 48px; color: var(--primary); }
    .blog-card-content { padding: 24px; }
    .blog-card-tag { display: inline-block; padding: 4px 12px; background: rgba(124, 58, 237, 0.1); color: var(--primary); border-radius: 100px; font-size: 12px; font-weight: 600; margin-bottom: 12px; }
    .blog-card h3 { font-size: 18px; margin-bottom: 8px; line-height: 1.4; }
    .blog-card p { font-size: 14px; color: var(--text-secondary); line-height: 1.6; }

    /* Enterprise CTA */
    .enterprise-cta { padding: 80px 0; background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%); color: white; }
    .enterprise-cta-inner { max-width: var(--container); margin: 0 auto; padding: 0 24px; display: grid; grid-template-columns: 2fr 1fr; gap: 64px; align-items: center; }
    .enterprise-cta h2 { font-size: 40px; margin-bottom: 16px; }
    .enterprise-cta p { font-size: 18px; opacity: 0.9; margin-bottom: 32px; }
    .enterprise-cta .btn { background: white; color: var(--primary); }
    .enterprise-cta .btn:hover { background: var(--bg-secondary); }
    .enterprise-cta-visual { text-align: center; }
    .enterprise-cta-stats { display: flex; flex-direction: column; gap: 24px; }
    .enterprise-stat { text-align: center; }
    .enterprise-stat-value { font-family: 'Plus Jakarta Sans', sans-serif; font-size: 36px; font-weight: 800; }
    .enterprise-stat-label { font-size: 14px; opacity: 0.8; }

    /* Testimonials */
    .testimonials { padding: 80px 0; }
    .testimonials-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 48px; }
    .testimonial-card { background: var(--white); border-radius: var(--radius-lg); padding: 32px; border: 1px solid var(--border); box-shadow: var(--shadow-sm); }
    .testimonial-quote { font-size: 15px; line-height: 1.7; color: var(--text); margin-bottom: 24px; font-style: italic; }
    .testimonial-author { display: flex; align-items: center; gap: 12px; }
    .testimonial-avatar { width: 44px; height: 44px; background: linear-gradient(135deg, var(--primary-light), var(--primary)); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: white; font-weight: 700; font-size: 16px; }
    .testimonial-info h4 { font-size: 14px; font-weight: 600; }
    .testimonial-info p { font-size: 13px; color: var(--text-secondary); }

    /* CTA Banner */
    .cta-banner { padding: 80px 0; background: var(--bg-secondary); }
    .cta-banner-inner { max-width: 800px; margin: 0 auto; text-align: center; }
    .cta-banner h2 { font-size: 40px; margin-bottom: 16px; }
    .cta-banner p { font-size: 18px; color: var(--text-secondary); margin-bottom: 32px; }
    .cta-banner .btn { padding: 16px 40px; font-size: 17px; }
    .cta-banner-sub { font-size: 14px; color: var(--text-secondary); margin-top: 16px; }

    /* Footer */
    .footer { padding: 64px 0 32px; background: var(--text); color: white; }
    .footer-grid { display: grid; grid-template-columns: 2fr repeat(4, 1fr); gap: 48px; margin-bottom: 48px; }
    .footer-brand p { font-size: 14px; opacity: 0.7; margin-top: 16px; line-height: 1.7; }
    .footer-col h4 { font-size: 14px; font-weight: 600; text-transform: uppercase; letter-spacing: 1px; opacity: 0.5; margin-bottom: 20px; }
    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 12px; }
    .footer-col a { font-size: 14px; opacity: 0.7; transition: opacity 0.2s; }
    .footer-col a:hover { opacity: 1; }
    .footer-bottom { padding-top: 32px; border-top: 1px solid rgba(255,255,255,0.1); display: flex; justify-content: space-between; align-items: center; font-size: 14px; opacity: 0.5; }

    /* Cookie Consent */
    .cookie-consent { position: fixed; bottom: 0; left: 0; right: 0; background: var(--white); border-top: 1px solid var(--border); padding: 24px; z-index: 9999; box-shadow: 0 -4px 20px rgba(0,0,0,0.1); display: none; }
    .cookie-consent.show { display: block; }
    .cookie-inner { max-width: var(--container); margin: 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; }
    .cookie-text { font-size: 14px; color: var(--text-secondary); }
    .cookie-text a { color: var(--primary); text-decoration: underline; }
    .cookie-actions { display: flex; gap: 12px; }
    .cookie-btn { padding: 10px 20px; border-radius: var(--radius); font-weight: 600; font-size: 14px; cursor: pointer; transition: all 0.2s; border: none; }
    .cookie-btn-accept { background: var(--primary); color: white; }
    .cookie-btn-accept:hover { background: var(--primary-dark); }
    .cookie-btn-reject { background: var(--bg-secondary); color: var(--text); border: 1px solid var(--border); }
    .cookie-btn-reject:hover { background: var(--bg-tertiary); }
    .cookie-btn-manage { background: none; color: var(--primary); text-decoration: underline; font-weight: 500; }
    .cookie-btn-manage:hover { opacity: 0.8; }

    /* Cookie Modal */
    .cookie-modal { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.5); z-index: 10000; display: none; align-items: center; justify-content: center; }
    .cookie-modal.show { display: flex; }
    .cookie-modal-content { background: var(--white); border-radius: var(--radius-xl); padding: 40px; max-width: 500px; width: 90%; max-height: 80vh; overflow-y: auto; }
    .cookie-modal h3 { font-size: 24px; margin-bottom: 8px; }
    .cookie-modal > p { font-size: 14px; color: var(--text-secondary); margin-bottom: 24px; }
    .cookie-category { padding: 20px 0; border-bottom: 1px solid var(--border); }
    .cookie-category:last-of-type { border-bottom: none; }
    .cookie-category-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
    .cookie-category h4 { font-size: 15px; font-weight: 600; }
    .cookie-category p { font-size: 13px; color: var(--text-secondary); }
    .toggle-switch { position: relative; width: 48px; height: 26px; }
    .toggle-switch input { opacity: 0; width: 0; height: 0; }
    .toggle-slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background: #CBD5E1; border-radius: 26px; transition: 0.3s; }
    .toggle-slider::before { content: ''; position: absolute; width: 20px; height: 20px; left: 3px; bottom: 3px; background: white; border-radius: 50%; transition: 0.3s; }
    .toggle-switch input:checked + .toggle-slider { background: var(--primary); }
    .toggle-switch input:checked + .toggle-slider::before { transform: translateX(22px); }
    .cookie-modal-actions { display: flex; gap: 12px; margin-top: 24px; }
    .cookie-modal-actions .btn { flex: 1; }

    @media (max-width: 1024px) {
      .hero-inner { grid-template-columns: 1fr; gap: 48px; }
      .hero h1 { font-size: 44px; }
      .feature-highlight-inner { grid-template-columns: 1fr; }
      .security-inner { grid-template-columns: 1fr; }
      .enterprise-cta-inner { grid-template-columns: 1fr; text-align: center; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
      .recorder-features, .editor-features, .features-grid { grid-template-columns: repeat(2, 1fr); }
      .testimonials-grid { grid-template-columns: repeat(2, 1fr); }
      .integration-grid { grid-template-columns: repeat(4, 1fr); }
